package com.pa.lcr.lcp;
public final class CrcLcp { public static final int ESC=0x1B, TILDE=0x7E, SEED=0x7E7E, POLY=0x1021; private CrcLcp(){} public static int crcUpdate(int crc,int b){ for(int i=7;i>=0;i--){ boolean fb=(crc&0x8000)!=0; crc=((crc<<1)&0xFFFF)|((b>>i)&1); if(fb) crc^=POLY;} return crc&0xFFFF;} public static int crcLcp(byte[] d){ int c=SEED; for(byte x:d) c=crcUpdate(c,x&0xFF); return c&0xFFFF;} public static byte[] escape(byte[] data){ java.io.ByteArrayOutputStream o=new java.io.ByteArrayOutputStream(); for(byte x:data){ int xi=x&0xFF; if(xi==ESC||xi==TILDE) o.write(ESC); o.write(xi);} return o.toByteArray(); }}
